package com.learningspace;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;
public class WidgetConfigActivity extends Activity{@Override public void onCreate(Bundle state){super.onCreate(state);int id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);setResult(RESULT_CANCELED);if(id==AppWidgetManager.INVALID_APPWIDGET_ID){finish();return;}new AlertDialog.Builder(this).setTitle("Choose your widget style").setItems(new String[]{"Light · quiet and warm","Forest · deep green"},(dialog,which)->{getSharedPreferences("widgets",0).edit().putString("theme_"+id,which==0?"light":"forest").apply();LearningWidget.updateAll(this);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id));finish();}).setOnCancelListener(d->finish()).show();}}
